function Counter() {
  const [count, setCount] = useState(0);

  useEffect(() => {
    const id = setInterval(() => {
      console.log(count);
    }, 1000);
    return () => clearInterval(id);
  }, []);

  return <button onClick={() => setCount(c => c + 1)}>Click</button>;
}

const ListItem = React.memo(({ onClick }) => <div>Item</div>);

function List() {
  const [text, setText] = useState('');

  // Parent re-renders on every keystroke
  const handleDelete = (id) => { console.log(id); };

  return (
    <>
      <input value={text} onChange={e => setText(e.target.value)} />
      <ListItem onClick={handleDelete} />
    </>
  );
}

